const raw = $input.first()?.json ?? {};
const body = raw.body ?? raw;

const event = (body.event ?? '').toString();
if (event !== 'message_created') return [];

if (body.private === true) return [];

const contentType = String(body.content_type ?? '').toLowerCase();
if (contentType !== 'text') return [];

const messageType = String(body.message_type ?? '').trim();
if (messageType !== '0' && messageType !== 'incoming') return [];

const incomingText = (body.content ?? '').toString().trim();
const conversationId = (body.conversation?.id ?? '').toString().trim();
if (!incomingText || !conversationId) return [];

const senderName =
  body.sender?.name ??
  body.meta?.sender?.name ??
  body.conversation?.meta?.sender?.name ??
  'prospect';

const senderEmail =
  body.sender?.email ??
  body.meta?.sender?.email ??
  body.conversation?.meta?.sender?.email ??
  '';

const senderPhone =
  body.sender?.phone_number ??
  body.meta?.sender?.phone_number ??
  body.conversation?.meta?.sender?.phone_number ??
  '';

return [{
  json: {
    conversation_id: conversationId,
    incoming_text: incomingText,
    sender_name: senderName,
    sender_email: senderEmail,
    sender_phone: senderPhone,
    fallback_reply: "Je n'ai pas pu générer une réponse. Un agent humain va vous contacter.",
    source_event: event
  }
}];

const historyResponse = $input.first()?.json ?? {};
const current = $('Filter Chatwoot event').first()?.json ?? {};

const MAX_HISTORY = 20;
const CALENDLY_LINK = 'https://calendly.com/contact-transferai/30min';
const PUBLIC_DOMAIN = 'https://www.transferai.ci';

function asArray(r) {
  if (Array.isArray(r)) return r;
  if (Array.isArray(r.payload)) return r.payload;
  if (Array.isArray(r.data)) return r.data;
  if (Array.isArray(r.messages)) return r.messages;
  return [];
}

const messages = asArray(historyResponse)
  .map((m) => {
    const content = (m.content ?? '').toString().trim();
    if (!content) return null;
    const isIn  = m.message_type === 0 || m.message_type === 'incoming' || m.message_type === 3;
    const isOut = m.message_type === 1 || m.message_type === 'outgoing';
    if (!isIn && !isOut) return null;
    return { role: isIn ? 'user' : 'assistant', content, ts: m.created_at || 0 };
  })
  .filter(Boolean)
  .sort((a, b) => a.ts - b.ts)
  .slice(-MAX_HISTORY)
  .map(({ role, content }) => ({ role, content }));

const lastUserInHistory = [...messages].reverse().find((m) => m.role === 'user')?.content ?? '';
const alreadyIncluded = lastUserInHistory === current.incoming_text;

const knownEmail = (current.sender_email || '').toString().trim();
const contactInfoStatus = knownEmail
  ? `L'email du prospect est déjà connu : ${knownEmail}. Ne le redemande surtout pas.`
  : "L'email du prospect n'est pas encore connu.";

const systemPrompt = [
  "Tu es l'assistant commercial et d'orientation de TransferAI Africa.",
  "Tu réponds en français ou en anglais selon la langue du DERNIER message du prospect.",
  "Ne mentionne jamais que tu changes de langue.",
  "Tu représentes une organisation centrée sur la formation IA, l'accompagnement entreprise, l'audit IA, la veille stratégique, l'automatisation, les catalogues sectoriels, les certifications, les webinaires et certains partenariats.",
  "Tu dois t'appuyer uniquement sur ces vérités métier. N'invente jamais d'offre, de prix, de calendrier, de référence client ou de promesse non confirmée.",
  "Tu disposes de l'historique récent. Utilise-le pour éviter de reposer les mêmes questions.",
  "Quand le besoin est simple, réponds d'abord utilement puis pose UNE seule question de qualification pertinente.",
  "Quand le besoin est plus large, pose au maximum DEUX questions de qualification par réponse.",
  "Questions de qualification prioritaires : organisation ou entreprise, secteur, objectif principal, email, site web.",
  "Règle contact importante : " + contactInfoStatus,
  "Règle rendez-vous : si le prospect demande explicitement un rendez-vous, un créneau, un appel, une démo, un échange avec l'équipe ou un accompagnement, donne IMMÉDIATEMENT ce lien : " + CALENDLY_LINK,
  "Tu peux demander l'email dans la même réponse pour le suivi, mais jamais comme condition préalable.",
  "Si le prospect demande les tarifs, explique brièvement que l'orientation dépend du besoin et propose un échange.",
  "Si la demande concerne emploi ou candidature, oriente vers la voie emploi et mise en relation.",
  "Si la demande concerne support ou accès technique, propose une reprise humaine.",
  "Si tu cites le site, utilise seulement des liens publics : " + PUBLIC_DOMAIN + ", /entreprises, /catalogue, /contact.",
  "Ton style : chaleureux, professionnel, clair, concret, sans jargon excessif.",
  "Ta réponse doit tenir en maximum 6 lignes courtes, avec une seule action principale à la fin."
].join(' ');

if (!systemPrompt.trim()) throw new Error('systemPrompt is empty — aborting');

const openaiMessages = [{ role: 'system', content: systemPrompt }, ...messages];

if (!alreadyIncluded && current.incoming_text) {
  openaiMessages.push({ role: 'user', content: current.incoming_text });
}

const safeMessages = openaiMessages.filter(m => m && typeof m.content === 'string' && m.content.trim() !== '');

if (safeMessages.length === 0) throw new Error('No valid messages to send — aborting');

return [{
  json: {
    conversation_id: current.conversation_id,
    incoming_text: current.incoming_text,
    sender_name: current.sender_name,
    sender_email: current.sender_email,
    sender_phone: current.sender_phone,
    fallback_reply: current.fallback_reply,
    history_count: messages.length,
    raw_history_messages: messages,
    openai_payload: {
      model: 'gpt-4.1-mini',
      temperature: 0.25,
      max_tokens: 420,
      messages: safeMessages
    }
  }
}];

const openai = $input.first()?.json ?? {};
const context = $('Build AI reply payload').first()?.json ?? {};

const replyText =
  openai.choices?.[0]?.message?.content?.toString().trim() ||
  context.fallback_reply ||
  "Je n'ai pas pu générer une réponse. Un agent humain va vous contacter.";

if (!replyText) throw new Error('reply_text is empty — aborting send');

return [{
  json: {
    ...context,
    reply_text: replyText
  }
}];

const format = $('Format AI reply').first()?.json ?? {};
const history = format.raw_history_messages ?? [];

const conversationText = history
  .map((m) => `${m.role === 'user' ? 'PROSPECT' : 'ASSISTANT'}: ${m.content}`)
  .join('\n');

const lastUserText = [...history].reverse().find((m) => m.role === 'user')?.content ?? '';
const conversationFull = lastUserText === format.incoming_text
  ? conversationText
  : `${conversationText}\nPROSPECT: ${format.incoming_text}`;

const systemPrompt = [
  "Tu es un agent de qualification commerciale pour TransferAI Africa.",
  "Analyse la conversation ci-dessous et extrais STRICTEMENT un objet JSON valide.",
  "Ne renvoie QUE du JSON. Aucun texte autour, aucun markdown, aucun commentaire.",
  "",
  "Intentions possibles : formation, audit_ia, veille, automatisation, catalogue, certification, webinar, partenariat, emploi, support, autre.",
  "Niveaux de sériosité : faible, moyen, eleve.",
  "crm_readiness_level possibles : none, contact_request_ready, prospect_target_ready.",
  "",
  "Règles :",
  "- utilise null si une information n'a JAMAIS été donnée.",
  "- ne devine pas, n'invente pas.",
  "- 'is_b2b' = true si le prospect parle au nom d'une organisation, false si particulier, null sinon.",
  "- 'wants_demo' = true si le prospect a explicitement demandé un rendez-vous, un appel, une démo.",
  "- 'needs_human_handoff' = true si la demande est stratégique, sensible, ou si le prospect demande un humain.",
  "- 'email' = email valide mentionné par le prospect, ou null.",
  "- 'phone' = téléphone mentionné par le prospect, ou null.",
  "- 'website' = site web explicitement mentionné par le prospect, ou null.",
  "- 'summary' = résumé très court et utile pour un humain.",
  "- 'next_best_action' = prochaine action concrète recommandée.",
  "",
  "JSON attendu (TOUTES ces clés obligatoires) :",
  "{\"company_name\": null, \"sector\": null, \"need_type\": null, \"intent\": null, \"lead_seriousness\": null, \"is_b2b\": null, \"wants_demo\": null, \"needs_human_handoff\": null, \"contact_name\": null, \"email\": null, \"phone\": null, \"website\": null, \"country\": null, \"summary\": null, \"next_best_action\": null, \"crm_readiness_level\": null, \"missing_fields\": []}"
].join('\n');

const userMessage = `Conversation à analyser :\n\n${conversationFull || 'PROSPECT: ' + format.incoming_text}\n\nProduis le JSON.`;

if (!systemPrompt.trim() || !userMessage.trim()) throw new Error('Qualification messages empty — aborting');

return [{
  json: {
    conversation_id: format.conversation_id,
    incoming_text: format.incoming_text,
    sender_name: format.sender_name,
    sender_email: format.sender_email,
    sender_phone: format.sender_phone,
    reply_text: format.reply_text,
    qualification_payload: {
      model: 'gpt-4.1-mini',
      temperature: 0.1,
      max_tokens: 650,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userMessage }
      ]
    }
  }
}];

const openai = $input.first()?.json ?? {};
const context = $('Build qualification payload').first()?.json ?? {};

const DEFAULT_QUALIFICATION = {
  company_name: null, sector: null, need_type: null, intent: null,
  lead_seriousness: null, is_b2b: null, wants_demo: null, needs_human_handoff: null,
  contact_name: null, email: null, phone: null, website: null, country: null,
  summary: null, next_best_action: null, crm_readiness_level: 'none',
  recommended_workflow: null, missing_fields: ['company_name', 'sector', 'need_type', 'email', 'website']
};

let qualification = { ...DEFAULT_QUALIFICATION };
let parseError = null;

try {
  const raw = openai.choices?.[0]?.message?.content?.toString().trim() || '{}';
  const parsed = JSON.parse(raw);
  qualification = { ...DEFAULT_QUALIFICATION, ...parsed };
} catch (err) {
  parseError = err.message;
}

if (!qualification.contact_name && context.sender_name && context.sender_name !== 'prospect') {
  qualification.contact_name = context.sender_name;
}
if (!qualification.email && context.sender_email) {
  qualification.email = context.sender_email;
}
if (!qualification.phone && context.sender_phone) {
  qualification.phone = context.sender_phone;
}

const labels = [];
const intent = (qualification.intent || '').toLowerCase();
const labelMap = {
  formation: 'formation', audit_ia: 'audit-ia', automatisation: 'automatisation',
  partenariat: 'partenariat', emploi: 'emploi', catalogue: 'catalogue',
  certification: 'certification', webinar: 'webinar', support: 'support', veille: 'veille'
};
if (labelMap[intent]) labels.push(labelMap[intent]);

const seriousness = (qualification.lead_seriousness || '').toLowerCase();
if (['eleve', 'élevé', 'high'].includes(seriousness)) labels.push('lead-chaud');
if (Array.isArray(qualification.missing_fields) && qualification.missing_fields.length > 0) labels.push('infos-manquantes');
if (qualification.needs_human_handoff === true) labels.push('handoff-humain');
if (qualification.wants_demo === true) labels.push('demo-proposee');
if (qualification.crm_readiness_level === 'contact_request_ready') labels.push('crm-contact-ready');
if (qualification.crm_readiness_level === 'prospect_target_ready') labels.push('crm-prospect-ready');

const customAttributes = {};
const fieldMap = {
  contact_name: 'contact_name', company_name: 'company_name', sector: 'sector',
  need_type: 'need_type', intent: 'intent', lead_seriousness: 'lead_seriousness',
  summary: 'internal_summary', next_best_action: 'next_best_action',
  country: 'country', website: 'lead_website', crm_readiness_level: 'crm_readiness_level',
  recommended_workflow: 'recommended_workflow', email: 'lead_email', phone: 'lead_phone'
};
for (const [src, dst] of Object.entries(fieldMap)) {
  if (qualification[src] != null) customAttributes[dst] = qualification[src];
}
if (typeof qualification.is_b2b === 'boolean') customAttributes.is_b2b = qualification.is_b2b;
if (typeof qualification.wants_demo === 'boolean') customAttributes.demo_proposed = qualification.wants_demo;
if (typeof qualification.needs_human_handoff === 'boolean') customAttributes.human_handoff = qualification.needs_human_handoff;

return [{
  json: {
    conversation_id: context.conversation_id,
    qualification,
    labels,
    custom_attributes_payload: { custom_attributes: customAttributes },
    labels_payload: { labels },
    parse_error: parseError
  }
}];
